def fig(name, caption):
    image = OUT / 'capturas' / name
    assert image.exists(), image
    return f'<figure><img src="{image.as_uri()}"><figcaption>{caption} Captura con datos de demostración.</figcaption></figure>'

def table(headers, rows):
    return '<table><thead><tr>' + ''.join(f'<th>{v}</th>' for v in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'

def write_doc(filename, title, subtitle, pages):
    count = len(pages)+1
    cover = f'<section class="page cover"><div class="eyebrow">Chatbox ITIL / Mesa de Ayuda Interna</div><h1>{title}</h1><div class="stripe"></div><p class="lead">{subtitle}</p><div class="meta"><p>Versión del software 1.0.0</p><p>Edición documental · 23 de septiembre de 2026</p><p class="small" style="color:#c1d0db">Documento elaborado sobre la implementación y las verificaciones de esta entrega.</p></div><div class="footer"><span>CHATBOX ITIL</span><span>01 / {count:02}</span></div></section>'
    body = cover
    for n, (section, heading, content) in enumerate(pages, 2):
        body += f'<section class="page"><div class="top"><span>CHATBOX ITIL</span><span>{title.upper()}</span></div><div class="eyebrow">{section}</div><h2>{heading}</h2><div class="content">{content}</div><div class="footer"><span>Versión 1.0.0 · Septiembre de 2026</span><span>{n:02} / {count:02}</span></div></section>'
    (OUT / filename).write_text(f'<!doctype html><html lang="es"><head><meta charset="UTF-8"><title>{title} — Chatbox ITIL</title><style>{STYLE}</style></head><body>{body}</body></html>', encoding='utf-8')

manual = [
('Guía de lectura', 'Usar el sistema con confianza', '''<p>Este manual está dirigido al personal de soporte que registra y atiende incidencias internas, consulta procedimientos y mantiene la base de conocimiento.</p><p>Las capturas corresponden a la interfaz de esta versión. Los nombres, cantidades y casos de las imágenes son ejemplos; no representan los registros de producción.</p><ul class="toc"><li><span>01. Inicio y cierre del sistema</span><b>3</b></li><li><span>02. Espacio de trabajo y tickets</span><b>4</b></li><li><span>03. Registrar un caso</span><b>5</b></li><li><span>04. Historial y bitácora</span><b>6</b></li><li><span>05. Derivar y cerrar</span><b>7</b></li><li><span>06. Consultar al agente y dictar por voz</span><b>8</b></li><li><span>07. Biblioteca de conocimiento</span><b>9</b></li><li><span>08. Crear y actualizar contenido</span><b>10</b></li><li><span>09. Documentos, imágenes y videos</span><b>11</b></li><li><span>10. Interpretar el Dashboard</span><b>12</b></li><li><span>11. Respaldo y solución de problemas</span><b>13</b></li></ul><div class="note">La bitácora es el registro oficial del caso. Documenta lo que intentaste, el resultado obtenido y el tiempo invertido.</div>'''),
('01 / Puesta en marcha', 'Inicio y cierre del sistema', '''<h3>Primera ejecución en Windows</h3><ol><li>Extrae completamente el paquete en una carpeta donde tengas permiso de escritura.</li><li>Conserva juntos <code>chatbox-itil.exe</code>, <code>public</code>, <code>data</code> y <code>node_modules</code>. El paquete incluye el motor; no necesitas instalar Node.js.</li><li>Para utilizar IA, configura <code>GEMINI_API_KEY</code> en el archivo <code>.env</code> del paquete. La copia distribuible no incluye la clave privada del equipo de desarrollo.</li><li>Abre <b>chatbox-itil.exe</b>. Mantén abierta la ventana del servidor.</li><li>Accede a <code>http://localhost:3000</code>. Con <code>OPEN_BROWSER=1</code>, el servidor intenta abrir el navegador automáticamente.</li></ol><h3>Uso diario</h3><p>Comprueba que la pantalla de Tickets cargue. En la parte inferior de la barra lateral, escribe el identificador del agente que realizará las acciones. Este identificador registra autoría operativa; no constituye un inicio de sesión.</p><h3>Cerrar correctamente</h3><p>Espera a que termine cualquier guardado, cierra el navegador y detén el servidor con <b>Ctrl + C</b> en su consola, o cierra esa ventana.</p><div class="note">Los registros se guardan en la carpeta <b>data</b>. No ejecutes el programa desde el interior del ZIP ni muevas únicamente el EXE a otra carpeta.</div>''' + table(['Configuración', 'Uso'], [('PORT', 'Puerto del servidor; valor de entrega: 3000.'), ('OPEN_BROWSER', '1: abrir navegador al iniciar; 0: no abrirlo.'), ('GEMINI_API_KEY', 'Clave del servicio de IA. No compartirla en capturas ni documentos.')]) ),
('02 / Navegación', 'Espacio de trabajo y tickets', fig('tickets-desktop.png', 'Figura 1. Vista principal de tickets y navegación lateral.') + '''<ol><li>Utiliza <b>Tickets</b> para buscar casos por el texto disponible, estado y prioridad.</li><li>Cambia la cantidad por página o utiliza <b>Anterior</b> y <b>Siguiente</b>.</li><li>Selecciona <b>Ver ticket</b> para leer la bitácora completa.</li><li>Utiliza <b>Consultar IA</b> en un caso en atención para abrir el agente con su contexto.</li></ol><p><b>Conocimiento</b> administra la biblioteca. <b>Dashboard</b> presenta los indicadores y los gráficos. En pantallas pequeñas, abre el menú de navegación para cambiar de sección.</p>'''),
('03 / Registro', 'Registrar un caso', fig('new-ticket-desktop.png', 'Figura 2. Formulario de registro de una incidencia interna.') + '''<ol><li>Desde Tickets, selecciona <b>Nuevo ticket</b>.</li><li>Describe quién reporta, qué ocurre y los datos solicitados: título, tipo, prioridad y alcance. Agrega el código patrimonial y el mensaje de error si corresponden.</li><li>Si usas la ayuda de IA para completar información, revisa cada dato sugerido antes de guardar.</li><li>Envía el registro y comprueba que aparezca en el listado.</li></ol><div class="note">Ejemplo: «La VPN no conecta desde las 09:00. Afecta a un equipo. Se verificó Internet y aparece error de certificado». Evita incluir contraseñas.</div>'''),
('04 / Trazabilidad', 'Historial y bitácora', fig('ticket-detail-desktop.png', 'Figura 3. Historial íntegro con autor, fecha, texto y minutos.') + '''<p>En <b>Ver ticket</b> se muestran las entradas originales en orden. Antes de continuar una atención, revisa qué se intentó, qué resultado tuvo y cuánto tiempo tomó.</p><ol><li>Regresa al listado y abre el menú de acciones del caso.</li><li>Selecciona <b>Dejar comentario</b>.</li><li>Escribe la acción y su resultado. Registra los minutos invertidos y guarda.</li><li>Vuelve al detalle y comprueba la nueva entrada.</li></ol><div class="note">Una corrección se registra como una nueva entrada. No se reemplaza ni se resume la bitácora con IA. Al cambiar de turno, el siguiente agente continúa a partir de este historial.</div>'''),
('05 / Atención', 'Derivar y cerrar con evidencia', fig('manual-derivacion.png', 'Figura 4. Derivación a un equipo con un motivo documentado.') + '''<h3>Derivar</h3><p>En el menú del ticket, selecciona <b>Derivar situación</b>, elige el equipo receptor y explica el motivo y las verificaciones realizadas. Confirma y comprueba el nuevo estado <b>Derivado</b>. El historial se conserva.</p><h3>Cerrar con ayuda del agente</h3><p>Abre <b>Consultar IA</b>, informa la solución que aplicaste y solicita el cierre. Selecciona la subcategoría técnica y confirma la opción de registro ofrecida: solución breve o conversación completa. Comprueba que el caso figure como <b>Cerrado</b> y que la solución aparezca en la bitácora.</p><p class="small">El cierre requiere solución y subcategoría. Un ticket cerrado no acepta las operaciones normales de derivación o comentario.</p>'''),
('06 / Asistencia', 'Consultar y dictar por voz', fig('manual-voz.png', 'Figura 5. Agente de soporte con campo de mensaje y botón de micrófono.') + '''<ol><li>Selecciona el caso desde <b>Consultar IA</b>, o entra a <b>Agente de soporte</b> para una consulta general.</li><li>Escribe tu pregunta o pulsa el <b>micrófono</b> y permite el acceso.</li><li>Habla en español. Pulsa nuevamente el micrófono para detener.</li><li>Revisa el texto reconocido y pulsa <b>Enviar</b>. El dictado no envía el mensaje por sí solo.</li><li>Consulta las fuentes que acompañan la respuesta y registra en la bitácora únicamente lo realmente realizado.</li></ol><div class="note">La voz requiere un navegador compatible y HTTPS o localhost. Si el servicio no está disponible, continúa escribiendo. El navegador puede procesar el audio mediante su propio servicio externo.</div>'''),
('07 / Biblioteca', 'Encontrar conocimiento útil', fig('knowledge-1366.png', 'Figura 6. Biblioteca con búsqueda, filtros y acciones de gestión.') + '''<ol><li>Abre <b>Conocimiento</b>.</li><li>Busca palabras del problema o filtra por tipo y categoría ITIL.</li><li>Selecciona <b>Ver</b> para leer el contenido y abrir sus adjuntos.</li><li>Comprueba el estado, la fuente y la fecha del conocimiento antes de aplicarlo.</li></ol><p>El agente utiliza los elementos <b>publicados</b> como fuentes. Los borradores o elementos pendientes de revisión pueden mantenerse en gestión sin considerarlos procedimientos aprobados.</p><p><b>Editar</b> modifica un elemento existente. <b>Eliminar</b> solicita confirmación y lo marca como inactivo; no aparece una opción de restauración en la interfaz actual.</p>'''),
('08 / Publicación', 'Crear y actualizar contenido', fig('manual-solucion.png', 'Figura 7. Ejemplo de una solución documentada; desplaza el formulario para acceder a Guardar.') + '''<ol><li>Pulsa <b>Agregar conocimiento</b> y selecciona texto, procedimiento, solución, documento, imagen o video según el recurso.</li><li>Completa título y contenido. Añade descripción, categoría ITIL, servicio, etiquetas y fuente cuando corresponda.</li><li>Selecciona el estado de publicación. Revisa las sugerencias generadas por IA.</li><li>Desplázate al final y pulsa <b>Guardar conocimiento</b>.</li><li>Busca el elemento y abre <b>Ver</b> para comprobarlo.</li></ol><p class="small">El sistema rechaza títulos duplicados activos y registros sin título o contenido. En una edición, comprueba los adjuntos conservados y los cambios antes de guardar.</p>'''),
('09 / Recursos', 'Documentos, imágenes y videos', fig('manual-video.png', 'Figura 8. Análisis de video mediante archivo o enlace.') + '''<p><b>Documentos:</b> selecciona PDF, DOCX o TXT. Extrae el texto y luego solicita el análisis para completar el contenido. Un PDF escaneado sin texto seleccionable puede requerir OCR fuera de esta función.</p><p><b>Imágenes:</b> adjunta las capturas y pulsa el análisis de imágenes. Revisa la interpretación antes de guardarla.</p><p><b>Videos:</b> utiliza un archivo admitido o un enlace público de YouTube. Espera los mensajes de progreso. Los videos enviados a análisis se procesan como temporales y no se conservan como adjuntos del conocimiento.</p><div class="note">Al pulsar <b>Cancelar</b> o cerrar el formulario, el resultado tardío no debe rellenar otro elemento. Límites de la interfaz: documentos 10 MB, imágenes 4 MB y análisis de video 256 MB por archivo. La IA necesita conexión y una clave válida.</div>'''),
('10 / Reportes', 'Interpretar el Dashboard', fig('dashboard-1366.png', 'Figura 9. Indicadores acumulados y actividad diaria del mes actual.') + '''<p><b>Registrados</b> cuenta todos los tickets históricos; <b>resueltos</b>, los cerrados. <b>Pendientes</b> incluye abiertos y en progreso. <b>Derivados</b> aparece por separado.</p><p>En el primer gráfico, cada barra indica la <b>cantidad de casos creados en un día del mes actual</b>. El número sobre la barra es la cantidad; un día sin barra tiene cero casos. El total del mes puede ser menor que el total histórico.</p><p>El segundo gráfico muestra el tiempo de resolución de los últimos casos cerrados con tiempo válido, en horas. El promedio y el mínimo excluyen los casos sin una duración válida.</p><div class="note">El tiempo de resolución mide el intervalo desde la creación hasta el cierre. No es la suma de los minutos de trabajo anotados en la bitácora.</div>'''),
('11 / Continuidad', 'Respaldo y solución de problemas', '''<h3>Respaldo recomendado</h3><ol><li>Detén el servidor después de terminar los guardados.</li><li>Copia la carpeta <b>data</b> completa, incluidos los adjuntos, a una ubicación de respaldo.</li><li>Conserva por separado una copia protegida de <b>.env</b>.</li><li>Para restaurar, detén el servidor, recupera la carpeta completa y vuelve a abrir el programa.</li></ol>''' + table(['Situación', 'Qué hacer'], [('La página no abre', 'Comprueba que la consola esté activa y que la dirección y el puerto coincidan.'), ('Puerto ocupado / EADDRINUSE', 'Evita abrir dos instancias. Revisa la instancia anterior o cambia PORT en .env y reinicia.'), ('La IA no responde', 'Revisa conexión, clave y disponibilidad del proveedor. Conserva tu texto y reintenta.'), ('Micrófono bloqueado', 'Permite el acceso en el navegador. Usa HTTPS o localhost. Puedes seguir escribiendo.'), ('No se reconoce la voz', 'Comprueba el dispositivo, reduce ruido y vuelve a iniciar el dictado.'), ('No se extrae un PDF', 'Comprueba que no esté protegido y que contenga texto. Prueba otra copia válida.'), ('El análisis tarda', 'Revisa el progreso. Si cancelas, vuelve a iniciar el análisis en el recurso correcto.'), ('No se guarda el cierre', 'Completa solución y subcategoría; verifica que el caso siga abierto.'), ('Faltan casos en el gráfico', 'El gráfico diario incluye solo el mes actual; las tarjetas conservan el total histórico.')]) + '''<p class="small">Esta versión se entrega como herramienta local. No dispone de autenticación de usuarios ni de permisos por rol. No publiques el servidor directamente en Internet.</p>''')
]

memory = [
('Identificación', 'Objeto y alcance del software', '''<p><b>Chatbox ITIL — Mesa de Ayuda Interna</b> es una aplicación para apoyar al personal de soporte en el registro, diagnóstico, seguimiento y documentación de incidencias. Integra atención conversacional, consulta de conocimiento y un historial verificable por ticket.</p><h3>Problema que atiende</h3><p>La información dispersa entre conversaciones y turnos dificulta continuar una atención. El sistema reúne el caso, sus acciones, tiempos y fuentes de consulta en un espacio común.</p><h3>Propósito</h3><p>Facilitar la continuidad del servicio, reutilizar soluciones y ofrecer indicadores de atención. La IA apoya el diagnóstico y la redacción; la bitácora conserva los hechos registrados.</p>''' + table(['Elemento', 'Descripción'], [('Versión', '1.0.0, revisión de entrega de septiembre de 2026.'), ('Usuarios principales', 'Agentes internos de soporte y equipos receptores de incidencias.'), ('Entorno de entrega', 'Windows x64; servidor local con interfaz en navegador.'), ('Tecnología', 'Node.js, JavaScript, HTML y CSS; datos JSON locales.'), ('Canales', 'Sistema central de agentes: tickets, asistencia, conocimiento y reportes.'), ('Límite del documento', 'Describe la implementación y sus verificaciones; no acredita certificación ITIL ni registro de propiedad intelectual.')]) + '''<div class="note">Autoría e institución se omiten por solicitud. No se atribuye el software a una entidad específica.</div>'''),
('Estructura', 'Mapa funcional', '''<div class="flow"><div>Registrar<br>el caso</div><div>Consultar<br>conocimiento</div><div>Documentar<br>acciones</div><div>Resolver<br>o derivar</div></div>''' + table(['Módulo', 'Funciones implementadas'], [('Tickets', 'Alta, consulta, búsqueda, filtros por estado y prioridad, paginación, detalle de historial y comentarios.'), ('Atención y trazabilidad', 'Registro de autor, fecha y minutos; derivación entre equipos; cierre con solución y subcategoría.'), ('Agente de soporte', 'Consultas generales o con ticket seleccionado, fuentes de conocimiento, sugerencias y acciones asistidas.'), ('Conocimiento', 'Alta, edición, consulta, búsqueda, clasificación, estados, eliminación lógica y adjuntos.'), ('Multimedia', 'Extracción de texto de PDF/DOCX/TXT, análisis de imágenes y videos, y enlaces públicos de YouTube.'), ('Dictado', 'Transcripción del navegador en español al campo del chat; revisión y envío manual.'), ('Dashboard', 'Totales históricos, separación pendientes/derivados, actividad diaria del mes actual y duración de resolución.')]) + '''<p>La navegación visible incluye un formulario de nuevo ticket además del chat. No se declara una entrada exclusivamente conversacional porque la interfaz actual ofrece ambos mecanismos.</p>'''),
('Diseño técnico', 'Arquitectura de la solución', '''<div class="flow"><div>Navegador<br>HTML · CSS · JS</div><div>Servidor HTTP<br>server.js</div><div>Rutas y servicios<br>lib/</div><div>Persistencia<br>JSON y adjuntos</div></div><p>El navegador consume una API HTTP. El servidor entrega los recursos estáticos y deriva las operaciones a las rutas. Los modelos calculan métricas y representan tickets; los servicios coordinan conversación, conocimiento y procesamiento de archivos.</p>''' + table(['Componente', 'Responsabilidad'], [('public/app.js y public/ui.js', 'Vistas, interacción, formularios, accesibilidad y representación del historial.'), ('public/voice-input.js', 'Ciclo del dictado, permisos, cancelación y escritura de texto reconocido.'), ('server.js / lib/router.js', 'Servidor HTTP, archivos estáticos y contratos de la API.'), ('models/ticket.js', 'Ticket, bitácora, cierre, derivación y cálculo de TFR/TTR/FCR.'), ('lib/storageAdapter.js', 'Lectura y escritura de tickets, conocimiento y archivos adjuntos.'), ('lib/knowledgeService.js', 'Proveedor de conocimiento, validación, clasificación y búsqueda.'), ('lib/documentService.js', 'Extracción de texto sin truncar el cuerpo del documento.'), ('lib/geminiService.js / lib/videoService.js', 'Integración con IA, cargas, plazos, validación y limpieza de temporales.')]) + '''<p class="small">El frontend no requiere compilación. El agrupamiento con esbuild se utiliza únicamente para producir el ejecutable del servidor.</p>'''),
('Información', 'Modelo y persistencia', table(['Dato del ticket', 'Finalidad'], [('id, título, tipo y prioridad', 'Identificación y descripción operativa del caso.'), ('categoria, subcategoriaTecnica', 'Clasificación general y técnica; la subcategoría es requerida al cerrar.'), ('equipoAsignado', 'Cola responsable: mesa de ayuda, área técnica, supervisor u otro equipo configurado.'), ('reportadoPor, atendidoPor, turno', 'Origen, agente de atención y contexto temporal.'), ('bitacora[]', 'Entradas con autor, texto original, fecha y minutosInvertidos. Se agregan, no se reemplazan.'), ('estado', 'abierto, en_progreso, derivado o cerrado. Se interpreta el estado histórico resuelto_pendiente como en_progreso.'), ('fechaCreacion y métricas', 'Base temporal, primera respuesta, resolución y primer contacto.'), ('Contexto conversacional', 'Indicadores de escalamiento, progreso del flujo y referencias a sugerencias.')]) + '''<h3>Organización de archivos</h3><p><code>data/tickets.json</code> contiene incidencias; <code>data/knowledge-items.json</code>, elementos de conocimiento; <code>data/knowledge-attachments/</code>, archivos binarios.</p><p>La configuración funcional vigente se lee de <code>data/knowledge-base.json</code>. Las rutas se resuelven desde la ubicación de la aplicación, también en el EXE.</p><div class="note">El adaptador abstrae tickets y conocimiento. Parte de la configuración aún utiliza acceso directo a JSON; la abstracción no cubre toda la persistencia.</div>'''),
('Procesos', 'Atención y conocimiento', '''<h3>Gestión de incidencias</h3><p>El registro incorpora la consulta y la primera respuesta. El agente agrega actuaciones, revisa casos similares y deriva cuando otra cola debe continuar. La derivación mantiene el historial. El cierre exige una solución documentada y una subcategoría técnica.</p><h3>Continuidad entre agentes</h3><p>No existe una ceremonia obligatoria de pase de turno. El equipo receptor accede al mismo caso y consulta la bitácora original, con tiempo y autor por acción.</p><h3>Gestión del conocimiento</h3><p>Conviven una base de respuestas y flujos configurables, y una biblioteca de documentos, procedimientos y soluciones. El proveedor consulta elementos publicados y devuelve fuentes para acompañar la respuesta del agente.</p><h3>Procesamiento multimedia</h3><p>PDF, DOCX y TXT se convierten a texto para consulta y análisis. Las imágenes se interpretan mediante IA. Los videos pasan por carga y procesamiento temporal, con mensajes de progreso y verificación de acceso al contenido antes de aceptar el resultado.</p><h3>Cancelación</h3><p>El formulario utiliza una señal de cancelación y descarta las respuestas de sesiones anteriores. Cerrar el formulario o abrir otro recurso impide que el análisis anterior sobrescriba el nuevo contenido.</p><h3>Voz</h3><p>La API SpeechRecognition del navegador produce texto en español. El usuario inicia y detiene la escucha y envía el texto explícitamente. La aplicación no guarda grabaciones de dictado.</p>'''),
('Indicadores', 'Cálculo e interpretación', table(['Indicador', 'Criterio de la versión'], [('TFR', 'Diferencia en minutos entre creación y primera entrada registrada por alguien distinto del reportante, incluida la respuesta automática del sistema.'), ('TTR', 'Diferencia en minutos entre creación y cierre; tiempo transcurrido, no horas laborables.'), ('FCR', 'Verdadero al cerrar cuando no hay una derivación registrada ni requerimiento de escalamiento según las reglas del modelo.'), ('Tiempo invertido', 'Suma de minutos de las entradas de bitácora para las tarjetas de tickets.'), ('Pendientes', 'Tickets abiertos o en progreso; excluye derivados y cerrados.'), ('Derivados', 'Tickets cuyo estado actual es derivado.'), ('Actividad diaria', 'Cantidad de tickets creados por día del mes y año actuales, interpretados en la zona horaria del navegador.'), ('Tiempo promedio / mínimo', 'Cerrados con duración de resolución numérica y válida.')]) + '''<p>Los indicadores se calculan a partir de fechas y estados. No se introducen manualmente en el formulario. El historial de acciones permite distinguir el tiempo efectivo trabajado del intervalo total de resolución.</p><div class="note">No se implementa un calendario de horas laborables ni un motor de SLA con pausas. No debe interpretarse TTR como un cálculo contractual de SLA.</div>'''),
('Validación', 'Verificaciones realizadas', table(['Área', 'Evidencia y alcance'], [('Backend real', 'Prueba aislada de registro, bitácora, derivación, cierre, filtros, similares, configuración y métricas.'), ('Conocimiento', 'Creación, duplicados, búsqueda, edición, eliminación lógica, adjuntos y descarga.'), ('Documentos', 'Extracción real de TXT, PDF y DOCX; comprobación del texto completo y anexos en pruebas unitarias.'), ('Video', 'Pruebas controladas de carga, progreso, tiempos de espera, limpieza y validación; servicio multimedia simulado.'), ('Interfaz', 'Navegación en cinco anchos: 360, 768, 1024, 1366 y 1920 px; modales, filtros, historial, fuentes y estados vacíos.'), ('Regresiones', 'Cancelación de video al abrir otro tipo; separación de pendientes y derivados; gráfico del mes actual.'), ('Dictado', 'Transcripción, cancelación, respuesta tardía y permiso denegado con reconocimiento simulado.'), ('IA real', 'Consulta sintética de texto a Gemini con resultado esperado; sin enviar datos de tickets.')]) + '''<h3>Correcciones durante la revisión</h3><p>Se corrigieron rutas dependientes de la carpeta de ejecución, la entrega de bytes al lector PDF, validaciones de comentarios y cierre, la suma de minutos y la derivación por IA mediante el modelo común.</p><p class="small">La verificación del EXE y los registros de ejecución se entregan en archivos JSON separados. Las pruebas automáticas no equivalen a una garantía sobre toda entrada posible ni sobre disponibilidad futura del proveedor externo.</p>'''),
('Distribución', 'Ejecutable y operación', '''<p>Se recuperó el método de empaquetado anterior, basado en <b>Node.js Single Executable Applications (SEA)</b>. El servidor se agrupa con esbuild, se prepara un recurso binario y se inyecta en una copia del runtime Windows x64 mediante postject.</p><p>El resultado conserva el EXE junto a los recursos web, los datos y las dependencias de ejecución. El destinatario no necesita instalar Node.js, pero debe conservar la carpeta completa.</p>''' + table(['Contenido', 'Tratamiento'], [('chatbox-itil.exe', 'Runtime y código del servidor de esta entrega.'), ('public/', 'Interfaz, estilos, dictado, iconos y tipografía local.'), ('node_modules/', 'Dependencias de producción con sus archivos de licencia.'), ('data/', 'Copia local de los registros y conocimiento al construir el paquete.'), ('.env', 'Configuración del paquete con la clave IA vacía; requiere configuración para usar Gemini.'), ('PDF de usuario y memoria', 'Documentación independiente para operación y descripción técnica.'), ('scripts/build-release.cjs', 'Proceso reproducible de construcción desde el proyecto fuente.')]) + '''<h3>Respaldo y actualización</h3><p>Antes de actualizar una instalación, detener el servidor y respaldar data y .env. No reemplazar los registros de una instalación activa con la copia incluida en un paquete de otra fecha.</p><p class="small">El ejecutable no está firmado con un certificado comercial. La firma del runtime original deja de ser válida al incorporar el código de la aplicación.</p>'''),
('Condiciones de uso', 'Límites y aspectos pendientes', '''<h3>Verificación presencial pendiente</h3><p>Se requiere probar el micrófono real, el reconocimiento con la voz del usuario y el análisis de imágenes/videos reales en el equipo de destino. El proveedor externo puede imponer límites, rechazar recursos o no estar disponible.</p><h3>Acceso y concurrencia</h3><p>La interfaz actual no implementa autenticación, autorización por roles ni aislamiento obligatorio entre colas. El identificador del agente es editable. El almacenamiento JSON no ofrece transacciones ni coordinación entre varias instancias; se debe operar una instancia por carpeta de datos.</p><h3>Portabilidad institucional</h3><p>La configuración vigente está en data/knowledge-base.json, no en la ruta config/knowledge-base.json descrita originalmente. Persisten textos y reglas auxiliares en código. La portabilidad de «reemplazar un único archivo sin ajustes» no queda acreditada por esta revisión.</p><h3>Licencia y autoría</h3><p>Los archivos del repositorio no son concordantes: LICENSE contiene MIT, package.json declara ISC y README.md indica derechos reservados. Esta revisión conserva esas declaraciones; debe definirse una licencia única antes de una publicación formal. No se inventan titulares ni se afirma que el expediente esté listo para un registro.</p><h3>Dependencias</h3><p>La entrega conserva avisos de terceros. No se realizó una auditoría legal completa de todas las licencias transitivas. La memoria describe características técnicas, no certifica cumplimiento jurídico.</p><div class="note">Estos límites no se ocultan bajo el resultado de las pruebas funcionales. Son condiciones de la implementación que deben considerarse al ampliar el despliegue.</div>'''),
('Referencia', 'Inventario y fuentes técnicas', '''<h3>Archivos de verificación</h3><ul><li><code>tests/release-integration.cjs</code>: backend real y modo de prueba del EXE.</li><li><code>tests/media-analysis.test.js</code>: comportamiento de documentos y videos.</li><li><code>tests/knowledge-routes.test.js</code>: rutas de análisis y extracción.</li><li><code>tests/redesign-smoke.cjs</code>: navegación, tamaños de pantalla y capturas.</li><li><code>tests/knowledge-ui-smoke.cjs</code>: regresiones de conocimiento, reportes y voz.</li></ul><h3>Fuentes oficiales de apoyo</h3><p>Node.js 22.18.0 — Single executable applications.<br><span class="small">https://nodejs.org/download/release/v22.18.0/docs/api/single-executable-applications.html</span></p><p>MDN Web Docs — SpeechRecognition.<br><span class="small">https://developer.mozilla.org/en-US/docs/Web/API/SpeechRecognition</span></p><h3>Glosario</h3>''' + table(['Término', 'Significado en el sistema'], [('Bitácora', 'Historial de acciones con autoría, fecha y duración declarada.'), ('Storage Adapter', 'Interfaz que separa las operaciones de almacenamiento de los consumidores.'), ('Conocimiento publicado', 'Contenido habilitado para consulta como fuente del agente.'), ('SEA', 'Mecanismo de Node.js para distribuir una aplicación junto con su runtime.'), ('Prueba aislada', 'Ejecución que utiliza una carpeta o respuestas de prueba y no modifica registros operativos.')]) + '''<p class="small">Las fuentes web explican las tecnologías empleadas. Las funcionalidades descritas se sustentan en la revisión del código y los registros de prueba de esta entrega.</p>''')
]

annexes = [
('Presentación', 'Guía de los anexos', '''<p>Este documento reúne evidencias visuales y técnicas del <b>sistema central Chatbox ITIL</b>. Está organizado para incorporarlo como anexos de un informe académico o técnico, conservando la numeración de cada figura y su fuente.</p><ul class="toc"><li><span>Anexo A. Espacio central de trabajo</span><b>3</b></li><li><span>Anexo B. Registro de incidencias</span><b>4</b></li><li><span>Anexo C. Historial y trazabilidad</span><b>5</b></li><li><span>Anexo D. Derivación entre equipos</span><b>6</b></li><li><span>Anexo E. Asistencia y dictado</span><b>7</b></li><li><span>Anexo F. Gestión del conocimiento</span><b>8</b></li><li><span>Anexo G. Reporte de atención</span><b>9</b></li><li><span>Anexo H. Arquitectura y datos</span><b>10</b></li><li><span>Anexo I. Matriz de verificación</span><b>11</b></li></ul><h3>Origen de las evidencias</h3><p>Las capturas muestran la interfaz ejecutada en un navegador, con datos ficticios preparados para las pruebas. Se utilizaron casos de VPN, correo e impresión para ilustrar el flujo de trabajo sin exponer registros operativos.</p><div class="note">Las figuras evidencian funcionalidades y presentación. Los valores de ejemplo no constituyen resultados de un estudio de campo ni demuestran una mejora estadística del servicio.</div><p class="small">Fuente general: elaboración a partir de la implementación local de Chatbox ITIL 1.0.0. Los resultados técnicos se respaldan en los registros de verificación incluidos con la entrega.</p>'''),
('Anexo A', 'Espacio central de trabajo', fig('tickets-desktop.png', 'Figura A.1. Gestión de tickets del sistema central.') + '''<h3>Elementos observables</h3><p>La barra lateral reúne Tickets, Agente de soporte, Conocimiento y Dashboard. El listado presenta prioridad, estado, equipo asignado, solicitante y accesos al detalle o a la asistencia.</p><h3>Relación con el informe</h3><p>Esta figura respalda la descripción del entorno unificado de atención: el agente puede localizar un caso, revisar su estado y acceder a las acciones necesarias desde la misma aplicación.</p><p><b>Criterio de verificación:</b> navegación funcional, filtros y paginación; presentación adaptable en cinco anchos de pantalla.</p><p class="small">El identificador de agente visible sirve para la autoría operativa. No representa autenticación ni autorización por roles.</p>'''),
('Anexo B', 'Registro de incidencias', fig('new-ticket-desktop.png', 'Figura B.1. Formulario de alta de un ticket.') + '''<h3>Información que se captura</h3><p>El registro incorpora reportante, título, descripción, tipo, prioridad y alcance. Los datos complementarios permiten precisar el equipo afectado y el mensaje de error.</p><h3>Escenario de referencia</h3><p>Un agente recibe una incidencia de acceso a VPN, describe el contexto, revisa la clasificación y registra el caso. El sistema asigna una identificación y conserva la consulta inicial.</p><p><b>Criterio de verificación:</b> una consulta válida genera el ticket y su bitácora; una consulta vacía se rechaza. El registro se puede recuperar desde el listado.</p><div class="note">La asistencia de IA para completar campos requiere revisión humana. No sustituye la validación de los hechos reportados.</div>'''),
('Anexo C', 'Historial y trazabilidad', fig('ticket-detail-desktop.png', 'Figura C.1. Bitácora íntegra de un caso de soporte.') + '''<h3>Evidencia de continuidad</h3><p>Las entradas se presentan con autor, fecha, texto y minutos invertidos. El agente entrante puede identificar qué acciones se ejecutaron y su resultado sin depender de un resumen generado por IA.</p><h3>Prueba asociada</h3><p>En la integración se registra un caso, se agrega una actuación, se deriva y se cierra. Se comparan las entradas iniciales con las recuperadas después de cada operación; el contenido original debe permanecer idéntico.</p><p><b>Resultado observado:</b> se conservaron las entradas y se añadieron únicamente las acciones correspondientes al flujo de prueba.</p><p class="small">Esta propiedad aplica al flujo de la aplicación. No equivale a un registro criptográfico ni impide una modificación externa de los archivos JSON.</p>'''),
('Anexo D', 'Derivación entre equipos', fig('manual-derivacion.png', 'Figura D.1. Selección del equipo receptor y motivo de derivación.') + '''<h3>Finalidad</h3><p>Cuando la atención requiere otro equipo, el agente registra el destino y el motivo. El ticket pasa al estado derivado y mantiene el historial disponible para continuar el diagnóstico.</p><h3>Prueba asociada</h3><p>Se envía una derivación válida al área técnica, se verifica el equipo y el estado resultantes y se compara la bitácora anterior. También se envía un equipo inexistente, que debe ser rechazado.</p><p><b>Resultado observado:</b> destino válido aceptado, destino no configurado rechazado e historial conservado.</p><div class="note">La derivación asistida por IA utiliza la misma operación del modelo que la derivación manual para mantener la validación y el cálculo de primer contacto.</div>'''),
('Anexo E', 'Asistencia y dictado por voz', fig('manual-voz.png', 'Figura E.1. Campo de consulta y micrófono del agente de soporte.') + '''<h3>Interacción</h3><p>El agente formula una consulta general o selecciona un ticket para aportar contexto. Puede escribir o dictar en español, detener la captura, revisar el texto reconocido y enviarlo.</p><h3>Verificación y alcance</h3><p>Las pruebas con reconocimiento simulado verifican transcripción, conservación del texto previo, cancelación, descarte de resultados tardíos y mensajes ante permisos denegados. Una consulta sintética confirmó la conectividad de texto con Gemini.</p><p><b>Pendiente presencial:</b> probar micrófono, permisos y calidad de reconocimiento con la voz del usuario en el equipo de destino.</p><p class="small">La disponibilidad de dictado depende del navegador y su servicio de reconocimiento. No se evaluó la precisión lingüística con una muestra de usuarios.</p>'''),
('Anexo F', 'Gestión del conocimiento', fig('knowledge-1366.png', 'Figura F.1. Biblioteca de procedimientos y documentos.') + '''<h3>Información gestionada</h3><p>La biblioteca permite clasificar, buscar, consultar, crear y editar conocimiento. Los elementos publicados pueden servir como fuentes del agente de soporte; la eliminación los marca como inactivos.</p><h3>Prueba asociada</h3><p>Se crea un elemento con un adjunto, se busca, se modifica y se descarga el archivo. Se comprueba el rechazo de un título duplicado y la exclusión del elemento tras su eliminación lógica.</p><p><b>Documentos:</b> se verificó la extracción real de TXT, PDF y DOCX. <b>Multimedia:</b> se verificaron flujos controlados de análisis, cancelación y tiempos de espera.</p><div class="note">La ejecución en vivo de imágenes y videos con el proveedor externo requiere una prueba adicional. Los escenarios simulados no acreditan el análisis de cualquier archivo.</div>'''),
('Anexo G', 'Reporte de atención', fig('dashboard-1366.png', 'Figura G.1. Indicadores y gráficos del Dashboard.') + '''<h3>Interpretación de la figura</h3><p>Las tarjetas distinguen registrados, resueltos, pendientes y derivados. El gráfico de barras representa los casos creados en cada día del mes actual. El gráfico de resolución utiliza los casos cerrados con tiempo válido.</p><h3>Prueba asociada</h3><p>Se preparan tickets del mes actual, del mes anterior y de otro año. Se verifica que solo el mes y año actuales se incluyan en las barras, y que los derivados no se sumen a los pendientes.</p><p><b>Resultado observado:</b> conteos separados y selección temporal correctos en los datos de prueba.</p><p class="small">Los valores ilustrados no deben trasladarse como métricas de producción a las conclusiones del informe.</p>'''),
('Anexo H', 'Arquitectura y estructura de datos', '''<div class="flow"><div>Navegador<br>Interfaz central</div><div>HTTP / API<br>Rutas</div><div>Servicios<br>Modelos</div><div>Adaptador<br>JSON y adjuntos</div></div><p>La interfaz utiliza HTML, CSS y JavaScript. El servidor Node.js atiende las solicitudes y coordina modelos, almacenamiento y servicios externos. El EXE incorpora el runtime para ejecutarse en Windows x64.</p>''' + table(['Entidad / recurso', 'Atributos o responsabilidad'], [('Ticket', 'Identificador, título, clasificación, prioridad, equipo, reportante, agente, turno y estado.'), ('Entrada de bitácora', 'Autor, texto original, fecha y minutos invertidos.'), ('Métricas', 'TFR y TTR desde fechas; resolución en primer contacto según derivaciones y escalamiento.'), ('Conocimiento', 'Título, contenido, tipo, categoría, estado, fuente, etiquetas y adjuntos.'), ('Configuración', 'Catálogos, respuestas y flujos de data/knowledge-base.json.'), ('Persistencia', 'Archivos JSON y binarios; adaptador para tickets y conocimiento.'), ('Integración de IA', 'Consultas y análisis mediante Gemini; reconocimiento de voz del navegador.')]) + '''<h3>Alcance de la arquitectura</h3><p>La versión no incorpora autenticación, permisos por rol ni transacciones entre múltiples instancias. Se recomienda una instancia por carpeta de datos. La configuración todavía contiene accesos directos a JSON.</p><p class="small">Diagrama elaborado a partir de la estructura del código. No representa infraestructura desplegada en una institución.</p>'''),
('Anexo I', 'Matriz de verificación funcional', table(['ID', 'Caso verificado', 'Resultado / método'], [('VF&#8209;01', 'Registro y recuperación de tickets', 'Aprobado · API real aislada.'), ('VF&#8209;02', 'Bitácora conservada tras comentario y derivación', 'Aprobado · comparación de entradas.'), ('VF&#8209;03', 'Cierre con solución y subcategoría', 'Aprobado · casos válidos e inválidos.'), ('VF&#8209;04', 'Filtros y casos similares', 'Aprobado · recuperación de casos esperados.'), ('VF&#8209;05', 'Conocimiento y adjuntos', 'Aprobado · crear, editar, buscar, descargar y desactivar.'), ('VF&#8209;06', 'Extracción de documentos', 'Aprobado · TXT, PDF y DOCX reales.'), ('VF&#8209;07', 'Cancelación y análisis de video', 'Aprobado en pruebas controladas; proveedor simulado.'), ('VF&#8209;08', 'Dashboard y mes actual', 'Aprobado · datos de varios meses y estados.'), ('VF&#8209;09', 'Dictado', 'Aprobado con reconocimiento simulado.'), ('VF&#8209;10', 'Interfaz adaptable', 'Aprobado · 360, 768, 1024, 1366 y 1920 px.'), ('VF&#8209;11', 'Ejecutable Windows', 'Validación del paquete en carpeta aislada y sin Node en PATH.'), ('VF&#8209;12', 'Conectividad de IA de texto', 'Consulta sintética al proveedor con resultado esperado.')]) + '''<h3>Evidencias reproducibles</h3><p><code>tests/release-integration.cjs</code>, <code>tests/redesign-smoke.cjs</code>, <code>tests/knowledge-ui-smoke.cjs</code>, <code>tests/media-analysis.test.js</code> y <code>tests/knowledge-routes.test.js</code>.</p><div class="note">La matriz documenta una revisión funcional de esta versión. No constituye una prueba de carga, auditoría de seguridad, evaluación de satisfacción ni certificación de cumplimiento.</div>''')
]

# Separar matriz y procedimiento de reproducción mantiene legibles las filas en A4.
section, heading, content = annexes[-1]
matrix, evidence = content.split('<h3>Evidencias reproducibles</h3>', 1)
annexes[-1] = (section, heading, matrix)
annexes.append(('Anexo J', 'Reproducción de las evidencias', '''<p>La revisión utiliza datos de prueba aislados. Las pruebas de interfaz simulan respuestas de la API; la integración ejecuta el backend real en otra carpeta. El modo de empaquetado ejecuta el EXE fuera del árbol del proyecto y sin Node en el PATH.</p><h3>Archivos de prueba</h3>''' + evidence + '''<h3>Comandos del proyecto</h3>''' + table(['Comando', 'Propósito'], [('npm test', 'Documentos, video controlado y rutas de conocimiento.'), ('npm run test:integration', 'Operaciones reales de la API con registros de prueba.'), ('npm run test:ui', 'Navegación, presentación, conocimiento, reportes y dictado simulado.'), ('npm run build:exe', 'Construcción del ejecutable Windows y sus dependencias.')]) + '''<h3>Registros de esta entrega</h3><p>Los archivos <code>verificacion-backend.json</code>, <code>verificacion-exe.json</code> y <code>verificacion-pdf.json</code> identifican los resultados de ejecución. <code>VERIFICACION.md</code> describe las correcciones y el alcance pendiente.</p><p class="small">Para repetir las pruebas de interfaz se necesita Chrome o Edge. La generación de capturas usa nombres y casos ficticios. Las pruebas no se deben ejecutar sobre la carpeta de datos operativos.</p>'''))
section, heading, content = annexes[0]
annexes[0] = (section, heading, content.replace('</ul>', '<li><span>Anexo J. Reproducción de las evidencias</span><b>12</b></li></ul>', 1))

